_CUE_WORDS = ['根本', '从来', '压根', '完全', '纯粹', '纯属', '无非', '只是', '只不过', '只会', '只想', '所谓', '什么', '哪来', '何来', '谈何', '都是', '全是', '不就是', '就是个', '就是在', '过时', '落后', '洗脑', '愚民', '谎言', '虚假', '编造', '捏造', '假的', '崩塌', '尽失', '绝望', '无力', '撕裂', '固化', '阴谋', '操控', '收割', '韭菜', '呵呵', '可笑', '荒谬', '笑话', '而已', '罢了', '垃圾', '恶心', '破防', '细思极恐', '没救', '没戏', '没希望', '看不到', '别信', '别被', '抹黑', '丑化', '打压', '黑幕', '裂痕', '一条心', '骗']
_CUE_RE = re.compile("[不没别甭非无未]|" + "|".join(map(re.escape, _CUE_WORDS)))
_SENT_RE = re.compile(r"[。！？!?；;\n]+")

def _has_cue(s): return bool(_CUE_RE.search(s))

def detect_major(text: str):
    """返回命中的重大风险规则编号列表（M1-M11）。逐句判定：
    STRONG 短语命中即判；WEAK 话题词需同句含贬损/否定线索。"""
    text = text or ""
    hit = set()
    for sent in _SENT_RE.split(text):
        if not sent.strip():
            continue
        cue = _has_cue(sent)
        for m in MAJOR_RULE_NAMES:
            if m in hit:
                continue
            if any(p in sent for p in STRONG_PHRASES.get(m, [])):
                hit.add(m)
            elif cue and any(p in sent for p in WEAK_PHRASES.get(m, [])):
                hit.add(m)
    return sorted(hit, key=lambda x: int(x[1:]))
